/* MacRunner 2026-08-29 — снимок окружения, см. include/hb_env.h. */
#include "hb_env.h"
#include "hb_gates.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

extern char** environ;

/* Снимок берётся один раз при загрузке модуля. Записей с запасом: реально
 * движок читает около полусотни гейтов, но окружение прогона может нести и
 * чужие переменные — лишние просто не поместятся, и для них hb_env вернёт то же,
 * что вернул бы getenv на момент старта: NULL. */
#define HB_ENV_MAX 512

struct hb_env_rec { const char* name; const char* value; unsigned hash; };
static struct hb_env_rec g_env[HB_ENV_MAX];
static unsigned g_env_n;
static int g_env_ready;

/* Указатель ищется за постоянное время, а не перебором.
 *
 * Зачем: hb_env зовут из 326 мест движка, и почти все имена начинаются
 * с "MACRUNNER_". Перебор сравнивал этот общий префикс с КАЖДОЙ записью
 * снимка, поэтому цена поиска росла быстрее числа переменных: 51 запись —
 * 106 нс, 71 запись — 249 нс. Это било по нам дважды. Во-первых, обвязка
 * замера сама выставляет несколько MACRUNNER_*, значит рука с бОльшим
 * числом гейтов дороже — наш прибор смещал собственные измерения. Во-вторых,
 * от этой цены мы отбивались кешированием в 70 местах, и каждый такой кеш
 * пришлось заводить в общий список для сброса (hb_gate_cache_register).
 * Дешёвый поиск снимает и то и другое: ни смещения, ни нужды в регистрациях.
 *
 * Открытая адресация с линейной пробой. Таблица строится один раз вместе
 * со снимком, дальше только читается, поэтому блокировок нет. */
#define HB_ENV_SLOTS 1024                       /* степень двойки, вдвое с запасом от HB_ENV_MAX */
static unsigned short g_slot[HB_ENV_SLOTS];     /* 0 — пусто, иначе индекс в g_env плюс один */

/* FNV-1a по имени до '=' (для строк снимка) либо до конца (для запроса). */
static unsigned hb_env_hash(const char* s)
{
    unsigned h = 2166136261u;
    for (; *s && *s != '='; s++) { h ^= (unsigned char)*s; h *= 16777619u; }
    return h;
}

/* Разбираем "ИМЯ=ЗНАЧЕНИЕ" прямо в строках environ: указатели остаются
 * валидными на всю жизнь процесса, копировать нечего. Имя не завершено нулём,
 * поэтому храним его длину неявно — через позицию '=' при сравнении. */
static void hb_env_snapshot(void)
{
    char** e;
    unsigned i;

    if (g_env_ready) return;
    for (e = environ; e && *e && g_env_n < HB_ENV_MAX; e++)
    {
        const char* eq = strchr(*e, '=');
        if (!eq) continue;
        g_env[g_env_n].name  = *e;      /* до '=' */
        g_env[g_env_n].value = eq + 1;
        g_env[g_env_n].hash  = hb_env_hash( *e );
        g_env_n++;
    }
    /* Раскладываем по слотам. Дубликат имени в environ невозможен по POSIX,
     * но если он всё же есть, побеждает ПЕРВЫЙ — ровно как в старом переборе. */
    for (i = 0; i < g_env_n; i++)
    {
        unsigned j = g_env[i].hash & (HB_ENV_SLOTS - 1);
        while (g_slot[j]) j = (j + 1) & (HB_ENV_SLOTS - 1);
        g_slot[j] = (unsigned short)(i + 1);
    }
    g_env_ready = 1;
}


/* ТАБЛИЦА ГЕЙТОВ. Перечисление и список имён порождены из самого кода
 * (scripts/породить-гейты.py), поэтому разойтись с ним не могут: имя,
 * добавленное в движок, попадает в таблицу при следующей генерации,
 * а имя, из движка убранное, из таблицы исчезает.
 *
 * Заполняется один раз. Поиск по имени тут ещё нужен — но ровно 260 раз
 * за жизнь процесса, около пяти микросекунд суммарно, вместо миллионов
 * раз на горячем пути. */
const char* hb_gate_tbl[HB_GATE_N];
int hb_gates_ready;

/* ОБЪЯВЛЕНИЕ ГЕЙТОВ — ОДНИМ МЕСТОМ, ИЗ ТАБЛИЦЫ.
 *
 * Раньше каждый гейт печатал себя сам, при первом обращении, и одноразовость
 * держалась на побочном действии соседнего кеша. 03.09.2026 это дважды
 * сломалось моей же рукой при переводе гейтов на таблицу: кеш перестал
 * заполняться, признак «первый раз» остался вечно истинным, и печать пошла на
 * каждый вызов — 666 578 строк в одном месте, 17 223 в другом. Журнал
 * раздувался, а запись журнала это часть замера, поэтому сравнение рук
 * становилось негодным, ничем себя не выдавая.
 *
 * Здесь одноразовость — свойство ПОСТРОЕНИЯ: таблица заполняется ровно один
 * раз на снимок окружения, и объявление идёт оттуда же. Сломать её отдельной
 * правкой в чужой функции нельзя.
 *
 * Печатаются только ЗАДАННЫЕ гейты: не заданный не влияет на прогон, а список
 * из 260 строк утопил бы журнал ради ничего.
 *
 * Имя берётся из hb_gate_imya, то есть из перечня, порождённого из самого кода
 * (scripts/породить-гейты.py). Значит «гейт объявлен» доказывает ровно то же,
 * что прежняя печать при первом обращении: имя не может разойтись с тем, что
 * читает движок. */
static void hb_gates_objavit(void)
{
    unsigned i;

    for (i = 0; i < (unsigned)HB_GATE_N; i++)
    {
        if (!hb_gate_tbl[i]) continue;
        fprintf( stderr, "macrunner-gate-таблица: %s=%s\n",
                 hb_gate_imya[i], hb_gate_tbl[i] );
    }
    fflush( stderr );
}

void hb_gates_fill(void)
{
    unsigned i;

    if (!g_env_ready) hb_env_snapshot();
    for (i = 0; i < (unsigned)HB_GATE_N; i++)
        hb_gate_tbl[i] = hb_env( hb_gate_imya[i] );
    hb_gates_ready = 1;
    hb_gates_objavit();
}

__attribute__((constructor))
static void hb_env_init(void) { hb_env_snapshot(); hb_gates_fill(); }

/* Переменной нет в снимке — значит она НЕ была задана при запуске процесса.
 * Возвращаем NULL и НЕ идём в getenv: именно ради этого снимок и делался.
 *
 * Ленивый догон через getenv, который тут стоял сначала, оказался хуже прямого
 * вызова: он кешировал ПЕРВОЕ увиденное значение навсегда, поэтому гейт,
 * который тест выставил и тут же снял (`set_env_var` / `restore_env_var`),
 * залипал включённым для всех последующих тестов. Приёмка встала на 99 % ЦП —
 * среди залипших оказался DIRECT_STACK, который вешает её и сам по себе.
 *
 * Тесты, меняющие окружение на ходу, обязаны позвать hb_env_refresh(). */
void hb_env_refresh(void)
{
    g_env_n = 0;
    g_env_ready = 0;
    memset( g_slot, 0, sizeof(g_slot) );
    hb_env_snapshot();
    /* Таблицу тоже перезаполняем, иначе после подмены окружения гейты
     * остались бы со старыми значениями — ровно тот отказ, из-за которого
     * когда-то залип DIRECT_STACK и повисла вся приёмка. */
    hb_gates_fill();
}

const char* hb_env(const char* name)
{
    unsigned h, j;
    size_t n;

    if (!name || !*name) return NULL;
    if (!g_env_ready) hb_env_snapshot();
    h = hb_env_hash( name );
    n = strlen( name );
    for (j = h & (HB_ENV_SLOTS - 1); g_slot[j]; j = (j + 1) & (HB_ENV_SLOTS - 1))
    {
        const struct hb_env_rec* rec = &g_env[g_slot[j] - 1];
        /* Сначала хеш — он отсекает чужие записи без единого сравнения байт.
         * Полное сравнение остаётся: хеш совпал ещё не значит имя совпало. */
        if (rec->hash == h && !strncmp( rec->name, name, n ) && rec->name[n] == '=')
            return rec->value;
    }
    /* Пустой слот — имени в снимке нет. Промах теперь тоже за постоянное время;
     * раньше он стоил ПОЛНОГО перебора, а промахов у нас большинство. */
    return NULL;
}

int hb_env_flag(const char* name, int def)
{
    const char* v = hb_env(name);

    if (!v) return def;
    if (!*v) return def;
    if (v[0] == '0' && v[1] == '\0') return 0;
    return 1;
}

int hb_env_skolko(void)
{
    if (!g_env_ready) hb_env_snapshot();
    return (int)g_env_n;
}
